  on conflict (client_id) do update
    set ended_at = coalesce(public.care_entries.ended_at, excluded.ended_at)
    where public.care_entries.deleted_at is null and public.care_entries.ended_at is null and excluded.ended_at is not null;

  -- 2. Milk bags still in the fridge on 20 Oct (the five open on 15 Oct came across then);
  --    and the three of those that have been used since.
  insert into public.milk_bottles (amount_ml, pumped_at, location, note, created_by)
  select v.ml, (v.d::date + case when v.src = 'night' then time '18:00' else time '03:00' end) at time zone 'UTC', 'fridge', 'Lovable bag ' || v.k, '00000000-0000-4000-8000-000000000002'
  from (values
    (90, '2026-10-16', 'morning', '5176fbbe'), (90, '2026-10-17', 'morning', 'c5ad328d'), (80, '2026-10-17', 'night', 'c85e7163'),
    (120, '2026-10-18', 'morning', '12722886'), (120, '2026-10-18', 'morning', '5b14b08d'), (90, '2026-10-19', 'morning', 'e26084a1'),
    (230, '2026-10-19', 'morning', '6038ef73'), (60, '2026-10-19', 'morning', '03c620cf'), (30, '2026-10-19', 'night', '16993c78'),
