  ) as v(ml, d, src, k)
  where not exists (select 1 from public.milk_bottles b where b.note = 'Lovable bag ' || v.k);
  update public.milk_bottles set used_at = '2026-10-15T09:41:40Z' where used_at is null and deleted_at is null and amount_ml = 140 and pumped_at::date = '2026-10-14';
  update public.milk_bottles set used_at = '2026-10-15T11:31:45Z' where used_at is null and deleted_at is null and amount_ml = 80 and pumped_at::date = '2026-10-15';
  update public.milk_bottles set used_at = '2026-10-17T04:08:02Z' where used_at is null and deleted_at is null and amount_ml = 180 and pumped_at::date = '2026-10-15';

  -- 3. Vaccinations given, from the Lovable vaccine book.
  insert into public.vaccinations (subject_id, schedule_id, given_on, place, note)
  select '00000000-0000-4000-8000-00000000a001', v.sid, v.d::date, v.place, v.note
  from (values
    ('bcg_1', '2026-06-06', 'NMC Royal Hospital, Abu Dhabi', 'Dr Sameh Abdelazim'),
    ('hepb_1', '2026-06-06', 'NMC Royal Hospital, Abu Dhabi', 'Dr Sameh Abdelazim'),
