    ('rota_2', '2026-10-15', 'NMC Royal Hospital, Abu Dhabi', null)
  ) as v(sid, d, place, note)
  where exists (select 1 from public.vaccine_schedule s where s.id = v.sid)
    and not exists (select 1 from public.vaccinations x where x.subject_id = '00000000-0000-4000-8000-00000000a001' and x.schedule_id = v.sid and x.deleted_at is null);

